function worldZonePreset(){
  return ['Asia/Shanghai','Asia/Tokyo','Asia/Kolkata','Europe/London','Europe/Paris',
    'America/New_York','America/Los_Angeles','America/Sao_Paulo','UTC','Australia/Sydney'];
}
function worldParts(zone, date){
  date = date || new Date();
  var fmt=new Intl.DateTimeFormat('en-GB',{timeZone:zone,hour12:false,
    year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',weekday:'short'});
  var p=fmt.formatToParts(date), o={};
  for(var i=0;i<p.length;i++) o[p[i].type]=p[i].value;
  var hh=o.hour==='24'?'00':o.hour;
  return { y:Number(o.year), m:Number(o.month), d:Number(o.day), hh:hh, mm:o.minute, ss:o.second, wd:o.weekday };
}
function worldOffsetMin(zone, date){
  date = date || new Date();
  var fmt=new Intl.DateTimeFormat('en-GB',{timeZone:zone,timeZoneName:'shortOffset'});
  var p=fmt.formatToParts(date), nm='';
  for(var i=0;i<p.length;i++) if(p[i].type==='timeZoneName') nm=p[i].value;
  var m=/GMT([+-])(\d{1,2})(?::(\d{2}))?/.exec(nm);
  if(!m) return 0;
  var h=Number(m[2]), mm=m[3]?Number(m[3]):0;
  return (m[1]==='-'?-1:1)*(h*60+mm);
}
function worldOffsetLabel(zone, date){
  var v=worldOffsetMin(zone,date);
  if(v===0) return 'UTC';
  var s=v<0?'-':'+', a=Math.abs(v);
  return 'UTC'+(v<0?'−':'+')+Math.floor(a/60)+':'+('0'+(a%60)).slice(-2);
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { worldZonePreset:worldZonePreset, worldParts:worldParts, worldOffsetMin:worldOffsetMin, worldOffsetLabel:worldOffsetLabel };
}
if (typeof window !== 'undefined') {
  window.WorldClockForgePure = { worldZonePreset:worldZonePreset, worldParts:worldParts, worldOffsetMin:worldOffsetMin, worldOffsetLabel:worldOffsetLabel };
}
